INSERT INTO questions (topic, question_en, question_ta, option_a_en, option_a_ta, option_b_en, option_b_ta, option_c_en, option_c_ta, option_d_en, option_d_ta, correct_answer, explanation_en, explanation_ta) VALUES
('Indian Polity', 'Which part of the Indian Constitution contains the fundamental rights?', 'இந்திய அரசியலமைப்பின் எந்த பகுதி அடிப்படை உரிமைகள் கொண்டது?', 'Part I', 'பகுதி I', 'Part III', 'பகுதி III', 'Part V', 'பகுதி V', 'Part VII', 'பகுதி VII', 'B', 'Fundamental rights are enshrined in Part III of the Constitution.', 'அடிப்படை உரிமைகள் அரசியலமைப்பின் பகுதி III இல் உள்ளன.'),
('Indian Polity', 'Who appoints the Chief Election Commissioner of India?', 'இந்தியத்தின் தலைமை தேர்தல் ஆணையாளரை யார் நியமிக்கிறார்?', 'Prime Minister', 'தலைமை செயலர்', 'President', 'நிர்வாகர்', 'Parliament', 'மன்றம்', 'Supreme Court', 'உச்ச நீதிமன்றம்', 'B', 'The President appoints the Chief Election Commissioner based on the advice of the Council of Ministers.', 'தலைமை தேர்தல் ஆணையாளரை அமைச்சர்கள் குழுவின் ஆலோசனைப்படி குடியரசுத் தலைவர் நியமிக்கிறார்.'),
('Indian Polity', 'Which amendment introduced the Goods and Services Tax in India?', 'இந்தியாவில் சரக்குகள் மற்றும் சேவைகள் வரியை அறிமுகப்படுத்திய திருத்தம் எது?', '101st Amendment', '101வது திருத்தம்', '97th Amendment', '97வது திருத்தம்', '42nd Amendment', '42வது திருத்தம்', '73rd Amendment', '73வது திருத்தம்', 'A', 'GST was introduced through the 101st Constitutional Amendment Act, 2016.', 'GST 101வது அரசியலமைப்பு திருத்தச் சட்டம் மூலம் அறிமுகப்படுத்தப்பட்டது.'),
('Indian Polity', 'What is the minimum age for a person to become the President of India?', 'இந்திய குடியரசுத் தலைவராக ஆக குறைந்த பட்ச வயது என்ன?', '30 years', '30 வயது', '35 years', '35 வயது', '40 years', '40 வயது', '25 years', '25 வயது', 'B', 'The Constitution requires the President to be at least 35 years old.', 'அரசியலமைப்பு குடியரசுத் தலைவர் குறைந்தது 35 வயதில் இருக்க வேண்டும் என்று சொல்கிறது.'),
('Indian Polity', 'Which article guarantees the right to freedom of speech and expression?', 'பேச்சு மற்றும் வெளிப்பாடின் உரிமையை எந்த கட்டுரை உறுதிசெய்கிறது?', 'Article 14', 'கட்டுரை 14', 'Article 19', 'கட்டுரை 19', 'Article 21', 'கட்டுரை 21', 'Article 32', 'கட்டுரை 32', 'B', 'Article 19 protects freedom of speech and expression.', 'பேச்சு மற்றும் வெளிப்பாடு பற்றிய உரிமையை கட்டுரை 19 காப்பாற்றுகிறது.'),
('Indian Polity', 'What is the term of the Lok Sabha?', 'லோக் சபாவின் காலம் என்ன?', '4 years', '4 ஆண்டுகள்', '5 years', '5 ஆண்டுகள்', '6 years', '6 ஆண்டுகள்', '3 years', '3 ஆண்டுகள்', 'B', 'The Lok Sabha has a term of five years unless dissolved earlier.', 'லோக் சபாவுக்கு பட்டியலெல்லாம் முன்பே முடிகிறது என்றால் அல்லாது ஐந்து வருட காலம் உள்ளது.'),
('Indian Polity', 'Who is the guardian of the Constitution?', 'அரசியலமைப்பின் காவலர் யார்?', 'Prime Minister', 'தலைமை செயலர்', 'President', 'நிர்வாகர்', 'Supreme Court', 'உச்ச நீதிமன்றம்', 'Attorney General', 'ஒழுங்கு ஆணையர்', 'C', 'The Supreme Court is considered the guardian of the Constitution.', 'உச்ச நீதிமன்றம் அரசியலமைப்பின் காவலராக கருதப்படுகிறது.'),
('Indian Polity', 'Which body resolves disputes between states?', 'மாநிலங்களுக்கிடையிலான மரியாதைகளை எது தீர்க்கிறது?', 'Parliament', 'மன்றம்', 'Supreme Court', 'உச்ச நீதிமன்றம்', 'President', 'நிர்வாகர்', 'Election Commission', 'தேர்தல் ஆணையம்', 'B', 'The Supreme Court adjudicates disputes between states.', 'மாநிலங்களுக்கிடையிலான மரியாதைகளை உச்ச நீதிமன்றம் தீர்த்துகொள்ளும்.'),
('Indian Polity', 'Under which article is the Right to Constitutional Remedies guaranteed?', 'அரசியலமைப்பு நிவாரண உரிமை எந்தக் கட்டுரையின் கீழ் உறுதி செய்யப்படுகிறது?', 'Article 32', 'கட்டுரை 32', 'Article 21', 'கட்டுரை 21', 'Article 19', 'கட்டுரை 19', 'Article 25', 'கட்டுரை 25', 'A', 'Article 32 guarantees the Right to Constitutional Remedies.', 'கட்டுரை 32 அரசியலமைப்பு நிவாரண உரிமையை உறுதிசெய்கிறது.'),
('Indian Polity', 'Who presides over a joint sitting of Parliament?', 'மன்றத்தின் இணைந்த அமர்வில் யார் தலைமை வகிக்கிறார்?', 'President', 'நிர்வாகர்', 'Prime Minister', 'தலைமை செயலர்', 'Speaker of Lok Sabha', 'லோக் சபா தலைவர்', 'Chief Justice of India', 'இந்திய உயர்நீதிமன்றத் தலைவர்', 'C', 'The Speaker of the Lok Sabha presides over joint sittings.', 'இணைந்த அமர்வில் லோக் சபா தலைவர் தலைமை வகிக்கிறார்.'),
('Indian Polity', 'Which schedule contains the allocation of powers between Union and State?', 'மத்திய அரசு மற்றும் மாநிலத்திற்கிடையிலான அதிகாரப் பகிர்வு எந்த அட்டவணையில் உள்ளது?', 'Seventh Schedule', 'ஏழாவது அட்டவணை', 'Sixth Schedule', 'ஆறாவது அட்டவணை', 'Tenth Schedule', 'பத்தாவது அட்டவணை', 'Fourth Schedule', 'நான்காவது அட்டவணை', 'A', 'The Seventh Schedule divides powers between Union and State.', 'ஏழாவது அட்டவணை மத்திய மற்றும் மாநில அதிகாரங்களைப் பிரிக்கிறது.'),
('Indian Polity', 'What is the maximum strength of the Council of Ministers?', 'மந்திரிமன்றத்தின் அதிகபட்ச பலம் என்ன?', '70', '70', '60', '60', '75', '75', '65', '65', 'C', 'The Council of Ministers can have a maximum of 15% of Lok Sabha strength, currently 75.', 'மந்திரிமன்றத்தில் லோக் சபா உறுப்பினர்களின் 15% அதிகபட்சமாக இருக்கலாம், தற்போது 75.'),
('Indian Polity', 'Which article defines the Directive Principles of State Policy?', 'மாநில அரசியல்திட்டத்தின் வழிகாட்டும் கொள்கைகள் எந்தக் கட்டுரையில் வரையறுக்கப்பட்டுள்ளன?', 'Article 36', 'கட்டுரை 36', 'Article 37', 'கட்டுரை 37', 'Article 38', 'கட்டுரை 38', 'Article 39', 'கட்டுரை 39', 'D', 'Directive Principles are defined in Article 39 of the Constitution.', 'அரசியலமைப்பில் வழிகாட்டும் கொள்கைகள் கட்டுரை 39 இல் வரையறுக்கப்படுகின்றன.'),
('Indian Polity', 'Who is the head of the state in India?', 'இந்தியாவில் மாநிலத்தின் தலைவர் யார்?', 'President', 'நிர்வாகர்', 'Prime Minister', 'தலைமை செயலர்', 'Chief Minister', 'முதல்வர்', 'Governor', 'ஆளுநர்', 'A', 'The President is the head of the state in India.', 'இந்தியாவில் குடியரசுத் தலைவர் மாநிலப்பெருமானாக இருக்கிறார்.'),
('Indian Polity', 'Which article provides for equality before law?', 'சட்டத்தின் முன் சமத்துவம் எந்த கட்டுரையில் உள்ளது?', 'Article 14', 'கட்டுரை 14', 'Article 15', 'கட்டுரை 15', 'Article 16', 'கட்டுரை 16', 'Article 17', 'கட்டுரை 17', 'A', 'Article 14 guarantees equality before the law.', 'சட்டத்தின் முன் சமத்துவத்தை கட்டுரை 14 உறுதிசெய்கிறது.'),
('Indian Polity', 'Which article protects the right to life and personal liberty?', 'வாழ்க்கை மற்றும் தனிப்பட்ட சுதந்திர உரிமையை எந்த கட்டுரை காப்பாற்றுகிறது?', 'Article 21', 'கட்டுரை 21', 'Article 22', 'கட்டுரை 22', 'Article 20', 'கட்டுரை 20', 'Article 19', 'கட்டுரை 19', 'A', 'Article 21 protects the right to life and personal liberty.', 'கட்டுரை 21 வாழ்க்கை மற்றும் தனிநபர் சுதந்திர உரிமையை பாதுகாக்கிறது.'),
('Indian Polity', 'What is the minimum age for Lok Sabha membership?', 'லோக் சபா உறுப்பினருக்கான குறைந்த பட்ச வயது என்ன?', '21 years', '21 வயது', '25 years', '25 வயது', '30 years', '30 வயது', '35 years', '35 வயது', 'B', 'A person must be at least 25 years old to be a Lok Sabha member.', 'லோக் சபா உறுப்பினர் ஆக குறைந்தது 25 வயது இருக்க வேண்டும்.'),
('Indian Polity', 'Which article allows a state to have a separate Election Commission?', 'ஒரு மாநிலத்திற்கு தனி தேர்தல் ஆணையம் ஆவதற்கு எந்த கட்டுரை அனுமதிக்கிறது?', 'Article 243K', 'கட்டுரை 243K', 'Article 324', 'கட்டுரை 324', 'Article 356', 'கட்டுரை 356', 'Article 30', 'கட்டுரை 30', 'A', 'Article 243K gives states the right to have their own Election Commission.', 'கட்டுரை 243K மாநிலங்களுக்கு தங்கள் சொந்த தேர்தல் ஆணையம் இருக்க உரிமை அளிக்கிறது.'),
('Indian Polity', 'Which body is responsible for drafting the Constitution?', 'அரசியலமைப்பை தயாரிப்பதில் பொறுப்பாக இருந்த அமைப்பு எது?', 'Constituent Assembly', 'உருவாக்கக் குழு', 'Drafting Committee', 'வரைவுக் குழு', 'Parliament', 'மன்றம்', 'National Assembly', 'தேசிய குழு', 'A', 'The Constituent Assembly drafted the Indian Constitution.', 'உருவாக்கக் குழு இந்திய அரசியலமைப்பை தயாரித்தது.'),
('Indian Polity', 'Which article protects freedom of religion?', 'மத சுதந்திரத்தை எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 25', 'கட்டுரை 25', 'Article 26', 'கட்டுரை 26', 'Article 28', 'கட்டுரை 28', 'All of these', 'மேலும் இவை அனைத்தும்', 'D', 'Articles 25, 26, and 28 together protect freedom of religion.', 'கட்டுரைகள் 25, 26 மற்றும் 28 ஒருங்கிணைந்தமாய் மத சுதந்திரத்தை பாதுகாக்கின்றன.'),
('Indian Polity', 'Who is the constitutional head of a state?', 'ஒரு மாநிலத்தின் அரசியலமைப்புச் தலைவர் யார்?', 'Chief Minister', 'முதல்வர்', 'Governor', 'ஆளுநர்', 'Speaker', 'துணை', 'Mayor', 'முகவர்', 'B', 'The Governor is the constitutional head of a state.', 'ஆளுநர் ஒரு மாநிலத்தின் அரசியலமைப்புச் தலைவராக இருக்கிறார்.'),
('Indian Polity', 'Under which article can President''s Rule be imposed?', 'குடியரசுத் தலைவரின் ஆணையம் எந்த கட்டுரையின் கீழ் விதிக்கப்படுகிறது?', 'Article 356', 'கட்டுரை 356', 'Article 352', 'கட்டுரை 352', 'Article 360', 'கட்டுரை 360', 'Article 370', 'கட்டுரை 370', 'A', 'President''s Rule is imposed under Article 356 in a state.', 'குடியரசுத் தலைவரின் ஆணையம் கட்டுரை 356 இன் கீழ் மாநிலத்தில் விதிக்கப்படுகிறது.'),
('Indian Polity', 'Which of the following is a Fundamental Duty?', 'பின்வரும் எந்த ஒன்று அடிப்படை கடமையை சேர்ந்தது?', 'Protect environment', 'சுற்றுச்சூழலைப் பாதுகாக்க', 'Vote in elections', 'தேர்தல்களில் வாக்களிக்க', 'Pay income tax', 'வருமான வரியைச் செலுத்த', 'Serve in the armed forces', 'சமாதானப் படையில் சேவை செய்ய', 'A', 'Protecting the environment is a Fundamental Duty under Article 51A.', 'சுற்றுச்சூழலைப் பாதுகாப்பது கட்டுரை 51A இல் அடிப்படை கடமை.'),
('Indian Polity', 'Which type of government is India classified as?', 'இந்தியா எந்த வகை அரசாக வகைப்படுத்தப்படுகிறது?', 'Federal', 'ஒருங்கிணைப்பான', 'Unitary', 'ஒற்றை', 'Confederal', 'கூட்டு', 'Semi-presidential', 'அரை குடியரசுத் தலைவர்', 'A', 'India is a federal polity with a strong centre.', 'இந்தியா வலுவான மையத்துடன் ஒரு கூட்டாட்சி அரசாகும்.'),
('Indian Polity', 'Which house is called the House of the People?', 'எந்த மன்றம் மக்கள் மன்றம் என்று அழைக்கப்படுகிறது?', 'Rajya Sabha', 'ராஜ்ய சபை', 'Lok Sabha', 'லோக் சபை', 'Vidhan Sabha', 'வिधान சபை', 'Legislative Council', 'சட்டமன்றம்', 'B', 'The Lok Sabha is called the House of the People.', 'மக்கள்மன்றம் லோக் சபை என்று அழைக்கப்படுகிறது.'),
('Indian Polity', 'The Emergency provisions are in which part of the Constitution?', 'அவசர நிர்ணயங்கள் அரசியலமைப்பின் எந்தப் பகுதியில் உள்ளன?', 'Part X', 'பகுதி X', 'Part XVIII', 'பகுதி XVIII', 'Part XV', 'பகுதி XV', 'Part XII', 'பகுதி XII', 'B', 'Emergency provisions are in Part XVIII of the Constitution.', 'அவசர நிர்ணயங்கள் அரசியலமைப்பின் பகுதி XVIII இல் உள்ளன.'),
('Indian Polity', 'Who resolves conflicts between the President and the Prime Minister?', 'குடியரசுத் தலைவர் மற்றும் பிரதமரின் மத்தியில் முரண்களை யார் தீர்க்கிறார்?', 'Parliament', 'மன்றம்', 'Supreme Court', 'உச்ச நீதிமன்றம்', 'Vice President', 'துணை நர-सீதி', 'Cabinet', 'மந்திரிக்குழு', 'B', 'The Supreme Court settles disputes between constitutional authorities.', 'உச்ச நீதிமன்றம் அரசியலமைப்பு அதிகாரிகள் மத்தியில் முரண்களை தீர்க்கிறது.'),
('Indian Polity', 'Which article guarantees equal pay for equal work?', 'சம வேலைக்கு சம ஊதியம் உறுதி செய்யப்படும் கட்டுரை எது?', 'Article 14', 'கட்டுரை 14', 'Article 16', 'கட்டுரை 16', 'Article 39(d)', 'கட்டுரை 39(d)', 'Article 21', 'கட்டுரை 21', 'C', 'Article 39(d) ensures equal pay for equal work.', 'சம பணிக்கு சம ஊதியம் கட்டுரை 39(d) மூலம் உறுதி செய்யப்படுகிறது.'),
('Indian Polity', 'What is the maximum number of ministers in a state cabinet?', 'ஒரு மாநிலத்தின் அமைச்சர் குழுவில் அதிகபட்சம் என்ன?', '15', '15', '20', '20', 'Maximum 25% of Legislative Assembly strength', 'மாநில சட்டமன்ற உறுப்பினர்கள் 25% ஆக அதிகபட்சம்', 'No limit', 'வரம்பில்லை', 'C', 'A state cabinet can have a maximum of 15% of the Legislative Assembly strength.', 'ஒரு மாநில அமைச்சர் குழு சட்டமன்ற உறுப்பினர்கள் 15% வரை மட்டுமே இருக்கலாம்.'),
('Indian Polity', 'Which institution protects the rights of Scheduled Castes and Scheduled Tribes?', 'திட்டவிதிக்கப்பட்ட ஜாதிகள் மற்றும் தத்தவங்களின் உரிமைகளை பாதுகாக்கும் நிறுவனம் எது?', 'National Commission for Backward Classes', 'பின்தங்கிய வகுப்புகள் தேசிய ஆணையம்', 'National Human Rights Commission', 'தேசிய மனித உரிமைகள் ஆணையம்', 'National Commission for Scheduled Castes and Scheduled Tribes', 'திட்டவிடப்பட்ட ஜாதிகள் மற்றும் தத்தவங்களுக்கு தேசிய ஆணையம்', 'Election Commission', 'தேர்தல் ஆணையம்', 'C', 'The National Commission for SC/ST safeguards their rights.', 'தி தேசிய ஆணையம் SC/ST உரிமைகளை பாதுகாக்கிறது.'),
('Indian Polity', 'Who supervises the implementation of fundamental rights?', 'அடிப்படை உரிமைகள் நடைமுறைக்கு வருவதை யார் கண்காணிக்கிறார்?', 'President', 'நிர்வாகர்', 'Supreme Court', 'உச்ச நீதிமன்றம்', 'Attorney General', 'ஒழுங்கு ஆணையர்', 'Prime Minister', 'தலைமை செயலர்', 'B', 'The Supreme Court ensures enforcement of fundamental rights.', 'அடிப்படை உரிமைகள் நடைமுறையாகும் என்பதை உச்ச நீதிமன்றம் உறுதிசெய்கிறது.'),
('Indian Polity', 'Which article deals with the right against exploitation?', 'அபயோகத்திற்கு எதிரான உரிமை எந்த கட்டுரையில் உள்ளது?', 'Article 23', 'கட்டுரை 23', 'Article 24', 'கட்டுரை 24', 'Article 25', 'கட்டுரை 25', 'Article 32', 'கட்டுரை 32', 'A', 'Article 23 prohibits trafficking and forced labor.', 'கட்டுரை 23 கடத்துதலும் கட்டாய உழைப்பு கடிக்கப்படாது.'),
('Indian Polity', 'What is the role of the Attorney General of India?', 'இந்திய சட்ட வல்லுநரின் பங்கு என்ன?', 'Heads the judiciary', 'நீதிபத்திரதிகாரத்தை தலைவர்', 'Advises the government on legal matters', 'அரசுக்கு சட்டப் பிரச்னைகளில் ஆலோசிக்க', 'Appoints judges', 'நீதிபதிகளை நியமிக்க', 'Leads Parliament sessions', 'மன்ற அமர்வுகளை தலைவர்', 'B', 'The Attorney General advises the government on legal issues.', 'சட்ட வல்லுனர் அரசுக்கு சட்டப் பிரச்சினைகளில் ஆலோசனை தருகிறார்.'),
('Indian Polity', 'Which schedule contains languages recognized by the Constitution?', 'அரசியலமைப்பு ஏற்றுக்கொண்ட மொழிகள் எந்த அட்டவணையில் உள்ளன?', 'Eighth Schedule', 'எட்டாவது அட்டவணை', 'Seventh Schedule', 'ஏழாவது அட்டவணை', 'Twelfth Schedule', 'பன்னிரண்டாவது அட்டவணை', 'Ninth Schedule', 'தொள்ளாவது அட்டவணை', 'A', 'The Eighth Schedule lists recognized languages.', 'எட்டாவது அட்டவணை ஏற்றுக்கொண்ட மொழிகளை பட்டியலிடுகிறது.'),
('Indian Polity', 'Which article provides for the appointment of the Prime Minister?', 'பிரதமர் நியமிப்பை எந்த கட்டுரை வழங்குகிறது?', 'Article 74', 'கட்டுரை 74', 'Article 75', 'கட்டுரை 75', 'Article 52', 'கட்டுரை 52', 'Article 78', 'கட்டுரை 78', 'B', 'The Prime Minister is appointed under Article 75.', 'பிரதமர் கட்டுரை 75 இன் கீழ் நியமிக்கப்படுகிறார்.'),
('Indian Polity', 'What is the function of the Finance Commission?', 'நிதி ஆணையத்தின் பணி என்ன?', 'Distribute tax revenue between Union and States', 'மத்திய மற்றும் மாநிலங்களுக்கு வரி வருமானத்தை பகிர', 'Conduct elections', 'தேர்தல்களை நடத்த', 'Appoint governors', 'ஆளுநர்களை நியமிக்க', 'Interpret the Constitution', 'அரசியலமைப்பை வெளிப்படுத்து', 'A', 'The Finance Commission recommends revenue sharing between Union and States.', 'நிதி ஆணையம் மத்திய மற்றும் மாநில வரி பகிர்வை பரிந்துரைக்கிறது.'),
('Indian Polity', 'Which type of directive principle focuses on social welfare?', 'சமூக நல்வாழ்வு மீது கவனம் செலுத்தும் வழிகாட்டும் கொள்கை வகை எது?', 'Economic', 'பொருளாதார', 'Political', 'அரசியல்', 'Social', 'சமூக', 'Religious', 'மத', 'C', 'Social justice and welfare are part of Directive Principles under Article 38.', 'சமூக நீதி மற்றும் நலன் கட்டுரை 38 இன் கீழ் வழிகாட்டும் கொள்கையில் உள்ளன.'),
('Indian Polity', 'Which constitutional body manages the public service exam process?', 'பொது சேவை தேர்வை எந்த அரசியலமைப்பு அமைப்பு நிர்வகிக்கிறது?', 'Election Commission', 'தேர்தல் ஆணையம்', 'Union Public Service Commission', 'மத்திய பொது சேவை ஆணையம்', 'Finance Commission', 'நிதி ஆணையம்', 'Law Commission', 'சட்ட ஆணையம்', 'B', 'The UPSC conducts civil services examinations in India.', 'UPSC இந்தியாவில் குடியரசு சேவை தேர்வுகளை நடத்துகிறது.'),
('Indian Polity', 'What is the minimum age to become a member of Rajya Sabha?', 'ராஜ்யசபா உறுப்பினராக கூட குறைந்த பட்ச வயது என்ன?', '25 years', '25 வயது', '30 years', '30 வயது', '35 years', '35 வயது', '40 years', '40 வயது', 'B', 'A person must be 30 years old to be elected to the Rajya Sabha.', 'ராஜ்யசபாவுக்கு 30 வயது இருக்க வேண்டும்.'),
('Indian Polity', 'Which article limits the powers of Parliament during an emergency?', 'அவசரநிலையில் மந்திரிமன்றத்தின் அதிகாரங்களை எந்த கட்டுரை கட்டுப்படுத்துகிறது?', 'Article 359', 'கட்டுரை 359', 'Article 352', 'கட்டுரை 352', 'Article 368', 'கட்டுரை 368', 'Article 320', 'கட்டுரை 320', 'A', 'Article 359 restricts fundamental rights during emergency.', 'அவசரநிலையில் கட்டுரை 359 அடிப்படை உரிமைகளைக் கட்டுப்படுத்துகிறது.'),
('Indian Polity', 'Which institution recommends names for appointment of judges to the Supreme Court?', 'உச்ச நீதிமன்ற நீதிபதிகளுக்கான பெயர்களை யார் பரிந்துரை செய்கிறார்?', 'Law Commission', 'சட்ட ஆணையம்', 'Collegium', 'கல்லூரியம்', 'Parliament', 'மன்றம்', 'President', 'நிர்வாகர்', 'B', 'The Supreme Court collegium recommends judge appointments.', 'உச்ச நீதிமன்ற கல்லூரியம் நீதிபதி நியமிப்புகளை பரிந்துரைக்கிறது.'),
('Indian Polity', 'Which article protects the educational rights of minorities?', 'اقلیت கள் கல்வி உரிமைகளை எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 29', 'கட்டுரை 29', 'Article 30', 'கட்டுரை 30', 'Article 25', 'கட்டுரை 25', 'Article 21', 'கட்டுரை 21', 'B', 'Article 30 protects the rights of minorities to establish educational institutions.', 'கட்டுரை 30 اقلیت கள் கல்வி நிறுவனங்களை நிறுவ உரிமையை பாதுகாக்கிறது.'),
('Indian Polity', 'What is the composition of the Union Cabinet?', 'மத்திய அமைச்சரவை அமைப்பு என்ன?', 'Only ministers of state', 'அமைச்சர்கள் மட்டும்', 'Prime Minister and Cabinet Ministers', 'பிரதமர் மற்றும் அமைச்சர்கள்', 'Only the President', 'நிர்வாகர் மட்டும்', 'Chief Ministers of states', 'மாநில முதல்வர்கள்', 'B', 'The Union Cabinet consists of the Prime Minister and Cabinet Ministers.', 'மத்திய அமைச்சரவை பிரதமர் மற்றும் அமைச்சர்கள் கொண்டது.'),
('Indian Polity', 'Which article empowers the Prime Minister to advise the President?', 'பிரதமருக்கு ஜனாதிபரிடம் ஆலோசனை வழங்க எந்த கட்டுரை அதிகாரமளிக்கிறது?', 'Article 74', 'கட்டுரை 74', 'Article 75', 'கட்டுரை 75', 'Article 83', 'கட்டுரை 83', 'Article 90', 'கட்டுரை 90', 'A', 'Article 74 mandates that the President acts on the Prime Minister''s advice.', 'கட்டுரை 74 பிரதமரின் ஆலோசனையில் ஜனாதிபர் செயல்படுவது கட்டுப்படுத்துகிறது.'),
('Indian Polity', 'Which part of the Constitution deals with the Union Government?', 'அரசியலமைப்பின் எந்தப் பகுதி மத்திய அரசை கையாள்கிறது?', 'Part III', 'பகுதி III', 'Part V', 'பகுதி V', 'Part VI', 'பகுதி VI', 'Part IX', 'பகுதி IX', 'B', 'Part V of the Constitution deals with the Union Government.', 'அரசியலமைப்பின் பகுதி V மத்திய அரசை கையாள்கிறது.'),
('Indian Polity', 'Which article grants reservation in government jobs for SC/ST?', 'SC/ST க்கான அரசு வேலைகளில் முன்பதிவு உரிமையை எந்த கட்டுரை வழங்குகிறது?', 'Article 15', 'கட்டுரை 15', 'Article 16', 'கட்டுரை 16', 'Article 17', 'கட்டுரை 17', 'Article 18', 'கட்டுரை 18', 'B', 'Article 16 allows reservation in public employment for SC/ST.', 'கட்டுரை 16 அரசு வேலைகளில் SC/ST மானாக்கத்தை அனுமதிக்கிறது.'),
('Indian Polity', 'Which body advises the President on appointment of governors?', 'ஆளுநர்களை நியமிப்பதில் குடியரசுத் தலைவருக்கு யார் ஆலோசனை அளிக்கிறார்?', 'Prime Minister', 'தலைமை செயலர்', 'Parliament', 'மன்றம்', 'Cabinet', 'மந்திரிக்குழு', 'Election Commission', 'தேர்தல் ஆணையம்', 'C', 'The Union Cabinet advises the President on governor appointments.', 'ஆளுநர் நியமிப்புகளில் மத்திய அமைச்சரவை ஜனாதிபருக்கு ஆலோசனை அளிக்கிறது.'),
('Indian Polity', 'Which article forbids discrimination on grounds of religion?', 'மதத்தை அடிப்படையாகக் கொண்டு மதிப்பீட்டைத் தடுக்கும் கட்டுரை எது?', 'Article 14', 'கட்டுரை 14', 'Article 15', 'கட்டுரை 15', 'Article 19', 'கட்டுரை 19', 'Article 25', 'கட்டுரை 25', 'B', 'Article 15 prohibits discrimination on grounds of religion and other categories.', 'மதத்தினால் மற்றும் பிற அடிப்படைகளால் மதிப்பீட்டை கட்டுரை 15 தடை செய்கிறது.'),
('Indian Polity', 'Which article enables Parliament to make laws for all India services?', 'அந்நிய சேவைகளுக்காக அனைத்து இந்தியா சட்டங்களை உருவாக்க Parlamento எந்த கட்டுரை அதிகாரமளிக்கிறது?', 'Article 312', 'கட்டுரை 312', 'Article 315', 'கட்டுரை 315', 'Article 320', 'கட்டுரை 320', 'Article 323', 'கட்டுரை 323', 'A', 'Article 312 empowers Parliament to create All India Services.', 'கட்டுரை 312 அனைத்து இந்திய சேவைகளை உருவாக்க Parlamento ஐ அதிகாரமளிக்கிறது.'),
('Indian Polity', 'What is the maximum tenure of the Election Commission in India?', 'இந்திய தேர்தல் சங்கத்தின் அதிகபட்ச காலவரம்பு எவ்வளவு?', '4 years', '4 ஆண்டுகள்', '5 years', '5 ஆண்டுகள்', '6 years', '6 ஆண்டுகள்', 'No fixed tenure', 'நிர்ணயிக்கப்பட்ட காலவரம்பு இல்லை', 'B', 'Election Commission members serve for six years or until age 65.', 'தேர்தல் ஆணைய உறுப்பினர்கள் ஆறு ஆண்டுகள் அல்லது 65 வயது வரை சேவை செய்கிறார்கள்.'),
('Indian Polity', 'Which article defines the structure of the Union Judiciary?', 'மத்திய நீதித்துறை அமைப்பை எந்த கட்டுரை வரையறுக்கிறது?', 'Article 124', 'கட்டுரை 124', 'Article 141', 'கட்டுரை 141', 'Article 32', 'கட்டுரை 32', 'Article 213', 'கட்டுரை 213', 'A', 'Article 124 establishes the Supreme Court and Union Judiciary.', 'கட்டுரை 124 உச்ச நீதிமன்றத்தை மற்றும் மத்திய நீதித்துறையை நிறுவுகிறது.'),
('Indian Polity', 'Which schedule lists forms of oaths and affirmations?', 'எந்த அட்டவணை சபாஷிங்களையும் உறுதிமொழிகளையும் பட்டியலிடுகிறது?', 'First Schedule', 'முதல் அட்டவணை', 'Third Schedule', 'மூன்றாவது அட்டவணை', 'Fifth Schedule', 'ஐந்தாவது அட்டவணை', 'Seventh Schedule', 'ஏழாவது அட்டவணை', 'B', 'The Third Schedule contains forms of oaths and affirmations.', 'மூன்றாவது அட்டவணை சபாஷிங்களையும் உறுதிமொழிகளையும் கொண்டுள்ளது.'),
('Indian Polity', 'Which article allows the President to promulgate ordinances?', 'உறுதிமொழிகள் வெளியிட குடியரசுத் தலைவர் எந்த கட்டுரை அனுமதிக்கிறார்?', 'Article 123', 'கட்டுரை 123', 'Article 122', 'கட்டுரை 122', 'Article 100', 'கட்டுரை 100', 'Article 154', 'கட்டுரை 154', 'A', 'The President can promulgate ordinances under Article 123.', 'கட்டுரை 123 இன் கீழ் குடியரசுத் தலைவர் உறுதிமொழிகளை வெளியிடலாம்.'),
('Indian Polity', 'What is the maximum strength of the Council of Ministers in the Union?', 'மத்திய அதிகாரிகளின் அதிகபட்ச பலம் என்ன?', '70', '70', '60', '60', '15% of Lok Sabha strength', 'லோக் சபா பலத்தின் 15%', '25% of Parliament strength', 'மன்ற பலத்தின் 25%', 'C', 'The Union Council of Ministers can be up to 15% of Lok Sabha strength.', 'மத்திய அமைச்சரவை லோக் சபா பலத்தின் 15% வரை இருக்கலாம்.'),
('Indian Polity', 'Which article provides for a joint sitting of Parliament?', 'மன்றத்தின் இணைந்த அமர்வு பற்றிய கட்டுரை எது?', 'Article 108', 'கட்டுரை 108', 'Article 100', 'கட்டுரை 100', 'Article 103', 'கட்டுரை 103', 'Article 110', 'கட்டுரை 110', 'A', 'Article 108 provides for a joint sitting of Parliament.', 'கட்டுரை 108 மன்றத்தின் இணைந்த அமர்வை அளிக்கிறது.'),
('Indian Polity', 'Which article protects the right to education for children?', 'மாணவர்களின் கல்வி உரிமையை எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 21A', 'கட்டுரை 21A', 'Article 19', 'கட்டுரை 19', 'Article 15', 'கட்டுரை 15', 'Article 31', 'கட்டுரை 31', 'A', 'Article 21A guarantees the right to education for children.', 'கட்டுரை 21A குழந்தைகளுக்கான கல்வி உரிமையை உறுதிசெய்கிறது.'),
('Indian Polity', 'Which part of Constitution deals with Panchayats?', 'நிறுவனங்களை எது அவர் அரசியலமைப்பின் பகுதி?', 'Part IX', 'பகுதி IX', 'Part X', 'பகுதி X', 'Part XI', 'பகுதி XI', 'Part XII', 'பகுதி XII', 'A', 'Part IX of the Constitution deals with Panchayats.', 'அரசியலமைப்பின் பகுதி IX பந்தையங்களை கையாள்கிறது.'),
('Indian Polity', 'Which article declares India a sovereign socialist secular democratic republic?', 'இந்தியாவை சாசூய்ய, சமூக, மதத் தனியாத ஜனநாயகக் குடியரசாக எந்த கட்டுரை கூறுகிறது?', 'Article 1', 'கட்டுரை 1', 'Article 12', 'கட்டுரை 12', 'Article 14', 'கட்டுரை 14', 'Article 25', 'கட்டுரை 25', 'A', 'Article 1 declares India a sovereign socialist secular democratic republic.', 'கட்டுரை 1 இந்தியாவை சுயாட்சி சமூக மதத் தனியாத ஜனநாயகக் குடியரசாக அறிவிக்கிறது.'),
('Indian Polity', 'Which article allows Parliament to amend the Constitution?', 'அரசியலமைப்பை மாற்ற Parlamento எதை அனுமதிக்கிறது?', 'Article 368', 'கட்டுரை 368', 'Article 369', 'கட்டுரை 369', 'Article 370', 'கட்டுரை 370', 'Article 375', 'கட்டுரை 375', 'A', 'Article 368 empowers Parliament to amend the Constitution.', 'கட்டுரை 368 அரசியலமைப்பை மாற்ற Parlamento ஐ அதிகாரமளிக்கிறது.'),
('Indian Polity', 'Which article protects cultural and educational rights of minorities?', 'اقلیت கள் பண்பாட்டு மற்றும் கல்வி உரிமைகளை எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 29', 'கட்டுரை 29', 'Article 30', 'கட்டுரை 30', 'Article 31', 'கட்டுரை 31', 'Article 32', 'கட்டுரை 32', 'A', 'Article 29 protects cultural and educational rights of minorities.', 'கட்டுரை 29 اقلیت கள் பண்பாட்டு மற்றும் கல்வி உரிமைகளை பாதுகாக்கிறது.'),
('Indian Polity', 'What is the maximum number of members in the Rajya Sabha?', 'ராஜ்ய சபையில் அதிகபட்ச உறுப்பினர்கள் எத்தனை?', '245', '245', '250', '250', '240', '240', '260', '260', 'C', 'The Rajya Sabha can have up to 245 members.', 'ராஜ்ய சபையில் அதிகபட்சம் 245 உறுப்பினர்கள் இருக்கலாம்.'),
('Indian Polity', 'Which article establishes the Election Commission?', 'தேர்தல் ஆணையத்தை எந்த கட்டுரை நிறுவுகிறது?', 'Article 324', 'கட்டுரை 324', 'Article 325', 'கட்டுரை 325', 'Article 326', 'கட்டுரை 326', 'Article 327', 'கட்டுரை 327', 'A', 'Article 324 establishes the Election Commission of India.', 'கட்டுரை 324 இந்திய தேர்தல் ஆணையை நிறுவுகிறது.'),
('Indian Polity', 'Which article deals with the appointment of the Chief Justice of India?', 'இந்திய உயர் நீதிபதியை நியமிப்பதில் எந்த கட்டுரை உள்ளது?', 'Article 124', 'கட்டுரை 124', 'Article 127', 'கட்டுரை 127', 'Article 124A', 'கட்டுரை 124A', 'Article 126', 'கட்டுரை 126', 'C', 'The Chief Justice is appointed under Article 124A and related conventions.', 'பிரதம நீதிபதி கட்டுரை 124A மற்றும் தொடர்புடைய நடைமுறைகளின் கீழ் நியமிக்கப்படுகிறார்.'),
('Indian Polity', 'What is the basic feature doctrine associated with?', 'அடிப்படை அம்சக் கொள்கை எந்ததுடன் தொடர்புடையது?', 'Judicial review', 'நீதிமன்ற பரிசீலனை', 'Financial policy', 'நிதி கொள்கை', 'Directive Principles', 'வழிகாட்டும் கொள்கைகள்', 'Fundamental duties', 'அடிப்படை கடமைகள்', 'A', 'The basic feature doctrine is linked to judicial review by the Supreme Court.', 'அடிப்படை அம்சக் கொள்கை உச்ச நீதிமன்றத்தின் நீதித்திட்ட பரிசீலனையுடன் தொடர்புடையது.'),
('Indian Polity', 'Which article preserves the powers of states during emergencies?', 'அவசரநிலைகளில் மாநில அதிகாரங்களை எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 358', 'கட்டுரை 358', 'Article 359', 'கட்டுரை 359', 'Article 355', 'கட்டுரை 355', 'Article 356', 'கட்டுரை 356', 'C', 'Article 355 directs the Centre to protect states during emergencies.', 'கட்டுரை 355 அவசரநிலைகளில் மாநிலங்களைப் பாதுகாக்க மையத்திற்கு வழிகாட்டுகிறது.'),
('Indian Polity', 'Which article protects freedom of movement?', 'சுற்றுமறிப்பு சுதந்திரத்தை எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 19', 'கட்டுரை 19', 'Article 21', 'கட்டுரை 21', 'Article 23', 'கட்டுரை 23', 'Article 25', 'கட்டுரை 25', 'A', 'Article 19(1)(d) protects freedom of movement.', 'கட்டுரை 19(1)(d) சுற்றுமறிப்பு சுதந்திரத்தை பாதுகாக்கிறது.'),
('Indian Polity', 'What is the role of the Comptroller and Auditor General?', 'கணக்காயர் மற்றும் மேலாளர் வழங்கும் பங்கு என்ன?', 'Review election disputes', 'தேர்தல் கருத்துகளை மதிப்பீடு செய்', 'Audit government expenditure', 'அரசு செலவுகளை கணக்கிட', 'Draft bills for finance', 'நிதி சட்டங்களை வரைவுசெய்', 'Manage public services', 'பொது சேவைகள் நிர்வகி', 'B', 'The CAG audits government receipts and expenditures.', 'CAG அரசு வரவுகள் மற்றும் செலவுகளை கணக்கிடுகிறது.'),
('Indian Polity', 'Which constitutional amendment introduced Panchayati Raj?', 'பஞ்சாயத்து ராஜை அறிமுகப்படுத்திய அரசியலமைப்பு திருத்தம் எது?', '73rd Amendment', '73வது திருத்தம்', '74th Amendment', '74வது திருத்தம்', '61st Amendment', '61வது திருத்தம்', '42nd Amendment', '42வது திருத்தம்', 'A', 'The 73rd Amendment established Panchayati Raj institutions.', '73வது திருத்தம் பஞ்சாயத்து ராஜ் அமைப்புகளை நிறுவியது.'),
('Indian Polity', 'Which part contains the provisions for the judiciary?', 'நீதித்துறைக்கான பிரிவுகள் எந்த பகுதியைச் சேர்ந்தது?', 'Part III', 'பகுதி III', 'Part V', 'பகுதி V', 'Part VI', 'பகுதி VI', 'Part IV', 'பகுதி IV', 'C', 'Part VI contains provisions for the Union Judiciary.', 'பகுதி VI மத்திய நீதித்துறைக்கு ஏற்பாடுகளை கொண்டுள்ளது.'),
('Indian Polity', 'Which article defines the powers of the President during war and national emergency?', 'போர் மற்றும் தேசிய அவசரநிலையின்போது குடியரசுத் தலைவரின் அதிகாரங்களை எந்த கட்டுரை வரையறுக்கிறது?', 'Article 352', 'கட்டுரை 352', 'Article 53', 'கட்டுரை 53', 'Article 78', 'கட்டுரை 78', 'Article 112', 'கட்டுரை 112', 'B', 'Article 53 defines the powers of the President under Article 352 and 356.', 'கட்டுரை 53 கட்டுரை 352 மற்றும் 356 இன் கீழ் குடியரசுத் தலைவரின் அதிகாரங்களை வரையறுக்கிறது.'),
('Indian Polity', 'Which article protects the right to property as a legal right?', 'சொத்து உரிமையை சட்ட உரிமையாக எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 300A', 'கட்டுரை 300A', 'Article 31', 'கட்டுரை 31', 'Article 19', 'கட்டுரை 19', 'Article 21', 'கட்டுரை 21', 'A', 'Article 300A makes the right to property a legal right.', 'கட்டுரை 300A சொத்து உரிமையை சட்ட உரிமையாக மாற்றுகிறது.'),
('Indian Polity', 'Who is responsible for administering oaths to members of Parliament?', 'மன்ற உறுப்பினர்களுக்கு சபாஷங் வழங்குவதற்குப் பொறுப்பானவர் யார்?', 'President', 'நிர்வாகர்', 'Speaker of Lok Sabha', 'லோக் சபா Sprecher', 'Prime Minister', 'தலைமை செயலர்', 'Chief Justice', 'மேல்நீதிபதி', 'B', 'The Speaker of Lok Sabha administers oaths to members.', 'லோக் சபா Sprecher உறுப்பினர்களுக்கு சபாஷங் அளிக்கிறார்.'),
('Indian Polity', 'Which article allows Parliament to prescribe the salary of judges?', 'நீதிபதிகளின் சம்பளத்தை நிர்ணய Parlamento எந்த கட்டுரை அனுமதிக்கிறது?', 'Article 125', 'கட்டுரை 125', 'Article 221', 'கட்டுரை 221', 'Article 280', 'கட்டுரை 280', 'Article 323', 'கட்டுரை 323', 'A', 'Article 125 allows Parliament to determine judges’ salaries.', 'கட்டுரை 125 நீதிபதிகளின் சம்பளத்தை நிர்ணய Parlamento ஐ அனுமதிக்கிறது.'),
('Indian Polity', 'Which article permits the Parliament to extend the jurisdiction of the Supreme Court?', 'உச்ச நீதிமன்றத்தின் உரிமையை நீட்ட Parlamento எந்த கட்டுரை அனுமதிக்கிறது?', 'Article 137', 'கட்டுரை 137', 'Article 141', 'கட்டுரை 141', 'Article 145', 'கட்டுரை 145', 'Article 218', 'கட்டுரை 218', 'C', 'Article 145 empowers Parliament to regulate Supreme Court procedure.', 'கட்டுரை 145 உச்ச நீதிமன்ற நடைமுறையை நிர்ணய Parlamento ஐ அதிகாரமளிக்கிறது.'),
('Indian Polity', 'Which article guarantees protection of interests of minorities?', 'பின்வட்ட மக்கள் வர்த்தகங்களை எந்த கட்டுரை உறுதிசெய்கிறது?', 'Article 29', 'கட்டுரை 29', 'Article 30', 'கட்டுரை 30', 'Article 31', 'கட்டுரை 31', 'Article 15', 'கட்டுரை 15', 'A', 'Article 29 protects the interests of minorities.', 'கட்டுரை 29 اقلیت கள் வர்த்தகங்களை பாதுகாக்கிறது.'),
('Indian Polity', 'Which schedule contains provisions for administration of tribal areas?', 'கூட்டிதழ் பகுதிகளின் நிர்வாகத்திற்கான ஏற்பாடுகள் எந்த அட்டவணையில் உள்ளன?', 'Fifth Schedule', 'ஐந்தாவது அட்டவணை', 'Sixth Schedule', 'ஆறாவது அட்டவணை', 'Seventh Schedule', 'ஏழாவது அட்டவணை', 'Eighth Schedule', 'எட்டாவது அட்டவணை', 'B', 'The Sixth Schedule contains provisions for administration of tribal areas.', 'ஆறாவது அட்டவணை பழங்குடி பகுதிகளின் நிர்வாகத்தை குறிக்கிறது.'),
('Indian Polity', 'Which article provides for the appointment of the Finance Commission?', 'நிதி ஆணையத்தை நியமிப்பதை எந்த கட்டுரை வழங்குகிறது?', 'Article 280', 'கட்டுரை 280', 'Article 312', 'கட்டுரை 312', 'Article 280A', 'கட்டுரை 280A', 'Article 315', 'கட்டுரை 315', 'A', 'Article 280 provides for the Finance Commission.', 'கட்டுரை 280 நிதி ஆணையத்தை ஏற்படுத்துகிறது.'),
('Indian Polity', 'Which article protects the rights of arrested persons?', 'போலீஸ் உட்படப்பட்டோர் உரிமைகளை எந்த கட்டுரை பாதுகாக்கிறது?', 'Article 22', 'கட்டுரை 22', 'Article 21', 'கட்டுரை 21', 'Article 20', 'கட்டுரை 20', 'Article 24', 'கட்டுரை 24', 'A', 'Article 22 protects rights of arrested persons.', 'கட்டுரை 22 கைது செய்யப்பட்டோரின் உரிமைகளை பாதுகாக்கிறது.'),
('Indian Polity', 'Which constitutional body supervises the pension system for government employees?', 'அரசு ஊழியர்களுக்கான ஓய்வூதிய முறையை எந்த அரசியல் அமைப்பு கண்காணிக்கிறது?', 'Finance Commission', 'நிதி ஆணையம்', 'Election Commission', 'தேர்தல் ஆணையம்', 'Union Public Service Commission', 'மத்திய பொது சேவை ஆணையம்', 'Comptroller and Auditor General', 'கணக்காயர் மற்றும் மேலாளர்', 'D', 'The CAG audits government financial management including pensions.', 'CAG ஓய்வூதியங்கள் உட்பட அரசாங்க நிதி மேலாண்மையை கணக்கிடுகிறது.'),
('Indian Polity', 'Which article clarifies the power of the President to grant pardons?', 'மன்னிப்பை வழங்க குடியரசுத் தலைவரின் அதிகாரத்தை எந்த கட்டுரை விளக்குகிறது?', 'Article 72', 'கட்டுரை 72', 'Article 74', 'கட்டுரை 74', 'Article 77', 'கட்டுரை 77', 'Article 79', 'கட்டுரை 79', 'A', 'Article 72 grants the President power to pardon.', 'கட்டுரை 72 குடியரசுத் தலைமையிடம் மன்னிப்பு அதிகாரத்தை அளிக்கிறது.'),
('Indian Polity', 'Which structure is known as the backbone of the Constitution?', 'அரசியலமைப்பின் முதுகெலும்பு எது என்று அழைக்கப்படுகிறது?', 'Fundamental Rights', 'அடிப்படை உரிமைகள்', 'Directive Principles', 'வழிகாட்டும் கொள்கைகள்', 'Federalism', 'கூட்டாட்சி', 'Judicial Review', 'நீதித்துறை பரிசீலனை', 'C', 'Federal structure is often called the backbone of the Constitution.', 'கூட்டாட்சி அமைப்பு அரசியலமைப்பின் முதுகெலும்பாக அழைக்கப்படுகிறது.'),
('Indian Polity', 'Under which article can the President proclaim Financial Emergency?', 'நிதி அவசரநிலையை குடியரசுத் தலைவர் எந்த கட்டுரையின் கீழ் அறிவிக்கலாம்?', 'Article 360', 'கட்டுரை 360', 'Article 352', 'கட்டுரை 352', 'Article 356', 'கட்டுரை 356', 'Article 368', 'கட்டுரை 368', 'A', 'Article 360 allows proclamation of Financial Emergency.', 'கட்டுரை 360 நிதி அவசரநிலையை அறிவிக்கும் உரிமையை வழங்குகிறது.'),
('Indian Polity', 'Which article ensures the right to constitutional remedies for fundamental rights violations?', 'அடிப்படை உரிமைகள் மீறப்பட்டால் அரசியலமைப்பு நிவாரண உரிமையை எந்த கட்டுரை உறுதிசெய்கிறது?', 'Article 32', 'கட்டுரை 32', 'Article 226', 'கட்டுரை 226', 'Article 19', 'கட்டுரை 19', 'Article 14', 'கட்டுரை 14', 'A', 'Article 32 allows petition to the Supreme Court for enforcement of fundamental rights.', 'கட்டுரை 32 அடிப்படை உரிமைகள் அமல்படுத்த உச்ச நீதிமன்றத்தை வழக்குப் பார்க்க அனுமதிக்கிறது.'),
('Indian Polity', 'Which ministry manages relations between Centre and States?', 'மையம் மற்றும் மாநிலங்களுக்கிடையிலான உறவுகளை எந்த அமைச்சகம் நிர்வகிக்கிறது?', 'Ministry of Home Affairs', 'உள்நகர்ப்புற வைத்திய அமைச்சகம்', 'Ministry of Finance', 'நிதி அமைச்சகம்', 'Ministry of External Affairs', 'பின்னர் அமைச்சகம்', 'Ministry of Law and Justice', 'சட்ட மற்றும் நியாய அமைச்சகம்', 'A', 'The Ministry of Home Affairs manages Centre-State relations.', 'உள்நகர்ப்புற வைத்திய அமைச்சகம் மையம்-மாநில உறவுகளை நிர்வகிக்கிறது.'),
('Indian Polity', 'Which article ensures equal opportunity in matters of public employment?', 'பொது வேலைகளில் சம வாய்ப்பை எந்த கட்டுரை உறுதிசெய்கிறது?', 'Article 14', 'கட்டுரை 14', 'Article 16', 'கட்டுரை 16', 'Article 19', 'கட்டுரை 19', 'Article 21', 'கட்டுரை 21', 'B', 'Article 16 guarantees equality of opportunity in public employment.', 'கட்டுரை 16 அரசு வேலைகளில் சம வாய்ப்பை உறுதிசெய்கிறது.'),
('Indian Polity', 'Which article defines the powers of the Finance Commission?', 'நிதி ஆணையத்தின் அதிகாரத்தை எந்த கட்டுரை வரையறுக்கிறது?', 'Article 280', 'கட்டுரை 280', 'Article 294', 'கட்டுரை 294', 'Article 150', 'கட்டுரை 150', 'Article 145', 'கட்டுரை 145', 'A', 'Article 280 defines the Finance Commission''s powers and functions.', 'கட்டுரை 280 நிதி ஆணையத்தின் அதிகாரங்கள் மற்றும் செயல்பாடுகளை வரையறுக்கிறது.'),
('Indian Polity', 'What is the role of the Prime Minister in the Council of Ministers?', 'மந்திரிமன்றத்தில் பிரதமரின் பங்கு என்ன?', 'Heads executive decisions', 'நிர்வாக முடிவுகளை தலைவராக', 'Presides over Cabinet meetings', 'மந்திரிக்குழு கூட்டங்களை தலைமையிட', 'Signs bills into law', 'சட்டமாக bills க்கு கையொப்பம் வைக்க', 'Advises the President', 'ஜனாதிபருக்கு ஆலோசனை தர', 'D', 'The Prime Minister advises the President and leads the Council of Ministers.', 'பிரதமர் ஜனாதிபருக்கு ஆலோசனை அளித்து மந்திரிமன்றத்தை வழிநடத்துகிறார்.'),
('Indian Polity', 'Which article gives Parliament power to make laws for whole or any part of India?', 'முழு அல்லது எந்த பகுதியின் இந்தியாவிற்கும் சட்டம் செய்ய Parlamento எந்த கட்டுரை அதிகாரமளிக்கிறது?', 'Article 245', 'கட்டுரை 245', 'Article 246', 'கட்டுரை 246', 'Article 247', 'கட்டுரை 247', 'Article 248', 'கட்டுரை 248', 'A', 'Article 245 grants Parliament power to make laws for the territory of India.', 'கட்டுரை 245 இந்தியா வெளியூராக சட்டம் செய்ய Parlamento ஐ அதிகாரமளிக்கிறது.');
